# register_reels.py <slug> [<slug> …] → writes src/reels/index.ts so Root.tsx has one composition per reel
import os, sys
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'src', 'reels')
imp, rows = [], []
for i, slug in enumerate(sys.argv[1:]):
    imp.append(f"import C{i} from './{slug}/Reel';\nimport R{i} from './{slug}/resolved.json';")
    rows.append(f"  {{ slug: '{slug}', Component: C{i}, R: R{i} as unknown as Resolved }},")
open(os.path.join(root, 'index.ts'), 'w').write(
    "// Generated by tools/register_reels.py — do not edit.\nimport type React from 'react';\nimport type { Resolved } from '../kit';\n" + '\n'.join(imp) +
    "\nexport const REELS: { slug: string; Component: React.FC<{ R: Resolved }>; R: Resolved }[] = [\n" + '\n'.join(rows) + "\n];\n")
print(f'registered {len(sys.argv) - 1} reel(s)')
